use std::any::{TypeId, type_name};

use crate::{
    Value,
    runtime::layout::Layout,
    value::{Ty, TypeRegistry},
};

/// A field in a Rust-backed Roto enum variant.
///
/// Values of this type are normally generated by [`RotoEnum`] implementations
/// produced by `#[derive(RotoEnum)]`.
#[derive(Clone, Debug)]
pub struct RotoEnumField {
    rust_name: &'static str,
    type_id: TypeId,
    layout: Layout,
}

impl RotoEnumField {
    /// Describe a field represented by `T` at the Roto boundary.
    #[doc(hidden)]
    pub fn of<T: Value>() -> Self {
        Self {
            rust_name: type_name::<T>(),
            type_id: T::resolve().type_id,
            layout: Layout::of::<T::Transformed>(),
        }
    }

    /// Return the Rust name of the field's boundary type.
    pub fn rust_name(&self) -> &'static str {
        self.rust_name
    }

    /// Return the [`TypeId`] of the field's boundary type.
    pub fn type_id(&self) -> TypeId {
        self.type_id
    }

    pub(crate) fn layout(&self) -> &Layout {
        &self.layout
    }
}

/// A variant in a Rust-backed Roto enum.
///
/// Values of this type are normally generated by [`RotoEnum`] implementations
/// produced by `#[derive(RotoEnum)]`.
#[derive(Clone, Debug)]
pub struct RotoEnumVariant {
    name: &'static str,
    tag: u8,
    doc: String,
    fields: Vec<RotoEnumField>,
}

impl RotoEnumVariant {
    /// Describe an enum variant.
    #[doc(hidden)]
    pub fn new(
        name: &'static str,
        tag: u8,
        doc: impl Into<String>,
        fields: Vec<RotoEnumField>,
    ) -> Self {
        Self {
            name,
            tag,
            doc: doc.into(),
            fields,
        }
    }

    /// Return the Roto name of this variant.
    pub fn name(&self) -> &'static str {
        self.name
    }

    /// Return the tag stored in this variant's stable representation.
    pub fn tag(&self) -> u8 {
        self.tag
    }

    /// Return the variant's documentation.
    pub fn doc(&self) -> &str {
        &self.doc
    }

    /// Return the fields of this tuple-style variant.
    pub fn fields(&self) -> &[RotoEnumField] {
        &self.fields
    }
}

/// An external Rust enum that has a stable representation for Roto.
///
/// Implementations should normally be generated with
/// [`#[derive(RotoEnum)]`](macro@crate::RotoEnum). The derive creates a
/// hidden `#[repr(u8)]` representation and converts between it and the
/// ordinary Rust enum, so Roto never depends on Rust's unspecified default
/// enum layout.
///
/// # Safety
///
/// `Repr`, [`RotoEnum::variants`], [`RotoEnum::into_repr`], and
/// [`RotoEnum::from_repr`] must describe the same variants in the same order.
/// `Repr` must use Rust's primitive enum representation with a `u8` tag,
/// equivalent to a union of C-layout variant structs whose first field is the
/// tag. Every variant description must report its actual, unique tag.
///
/// The conversion methods transfer ownership. They must neither duplicate nor
/// prematurely drop any field or custom enum state. Implementing this trait
/// manually requires accounting for any custom [`Drop`] implementation.
pub unsafe trait RotoEnum: Sized + 'static {
    /// Stable representation exchanged with generated Roto code.
    type Repr: Clone + PartialEq + Send + Sync + 'static;

    /// Convert the Rust enum to its stable Roto representation.
    #[doc(hidden)]
    fn into_repr(self) -> Self::Repr;

    /// Convert the stable Roto representation back to the Rust enum.
    #[doc(hidden)]
    fn from_repr(repr: Self::Repr) -> Self;

    /// Describe all variants, in discriminant order.
    fn variants() -> Vec<RotoEnumVariant>;
}

pub(crate) fn resolve_enum<T: RotoEnum>() -> Ty {
    TypeRegistry::store::<T>(super::TypeDescription::Enum)
}
